{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_quicksort_basic_mechanism",
      "facet": "mechanism",
      "statement": "Quicksort is an algorithm that picks an element from the array (the pivot), partitions the remaining elements into those greater than and less than this pivot, and recursively sorts the partitions.",
      "start_line": 5,
      "end_line": 9
    },
    {
      "key": "obs_quicksort_variants",
      "facet": "other",
      "statement": "There are many variants of the basic quicksort scheme regarding pivot selection, partitioning, recursion stopping conditions, and switching to other algorithms for small partitions.",
      "start_line": 9,
      "end_line": 9
    },
    {
      "key": "obs_quicksort_classification",
      "facet": "property",
      "statement": "Quicksort is an in-place sort and a Las Vegas algorithm when the pivot is picked randomly.",
      "start_line": 12,
      "end_line": 15
    },
    {
      "key": "obs_quicksort_specializations",
      "facet": "relation",
      "statement": "Balanced quicksort, multikey Quicksort, and introspective sort are specializations of quicksort.",
      "start_line": 18,
      "end_line": 23
    },
    {
      "key": "obs_quicksort_components",
      "facet": "relation",
      "statement": "Quicksort uses partition, divide and conquer, recursion, and Select as components or related concepts.",
      "start_line": 30,
      "end_line": 38
    },
    {
      "key": "obs_quicksort_performance_worst_case",
      "facet": "property",
      "statement": "Quicksort has a running time of Θ(n²) in the worst case.",
      "start_line": 46,
      "end_line": 49
    },
    {
      "key": "obs_quicksort_performance_typical",
      "facet": "property",
      "statement": "Quicksort is typically O(n log n).",
      "start_line": 50,
      "end_line": 51
    },
    {
      "key": "obs_quicksort_practical_performance",
      "facet": "property",
      "statement": "In practical situations, a finely tuned implementation of quicksort beats most sort algorithms, including sort algorithms whose theoretical complexity is O(n log n) in the worst case.",
      "start_line": 52,
      "end_line": 52
    },
    {
      "key": "obs_quicksort_select_variant",
      "facet": "mechanism",
      "statement": "Select can be used to always pick good pivots, thus giving a variant with O(n log n) worst-case running time.",
      "start_line": 53,
      "end_line": 56
    },
    {
      "key": "obs_dual_pivot_performance",
      "facet": "property",
      "statement": "Newer variants, such as dual-pivot quicksort, are faster because they access less memory.",
      "start_line": 57,
      "end_line": 59
    }
  ],
  "claims": [
    {
      "key": "claim_select_worst_case_guarantee",
      "status": "DERIVED_INTERPRETATION",
      "supported_by": [
        "obs_quicksort_performance_worst_case",
        "obs_quicksort_select_variant"
      ],
      "statement": "Using the Select algorithm for pivot selection transforms quicksort from having a Θ(n²) worst-case running time to an O(n log n) worst-case running time."
    },
    {
      "key": "claim_dual_pivot_efficiency",
      "status": "DERIVED_INTERPRETATION",
      "supported_by": [
        "obs_dual_pivot_performance"
      ],
      "statement": "Dual-pivot quicksort achieves higher performance than standard quicksort primarily through reduced memory access."
    }
  ],
  "questions": []
}
